def parse_outcome(cell: str) -> str | None:
        if cell is None:
            return None
        s = str(cell).strip()
        if s == "" or s.lower() == "nan":
            return None
        if "Penalty scored" in s:
            return "scored"
        if "Penalty missed" in s:
            return "missed"
        return None

